mapper.select:
/*
내가 팔로우 하는 사람

범위처리 해야됨...
*/
 SELECT fs.followed_user_id as customerId,
     NULL AS username
FROM follows fs
WHERE fs.following_user_id = #{userId}
ORDER BY fs.followed_user_id
LIMIT #{limit} OFFSET #{offset}

/*
나를 팔로우 하는 사람
*/
 SELECT fs.following_user_id as customerId,
     NULL as username
FROM follows fs
WHERE fs.followed_user_id = #{userId}
ORDER BY fs.following_user_id
LIMIT #{limit} OFFSET #{offset}

/*
나를 팔로우 하는 사람수
*/

SELECT count(fs.followed_user_id)
FROM follows fs
WHERE fs.followed_user_id = #{userId}

/*
내가 팔로우 하는 사람수
*/

SELECT count(fs.following_user_id)
FROM follows fs
WHERE fs.following_user_id = #{userId}

mapper.delete:
DELETE FROM follows
WHERE following_user_id = #{followingUserId}
  AND followed_user_id = #{followedUserId}
